import imageSizes from "@/data/imageSizes.json";

type Size = { w: number; h: number };

const SIZES = imageSizes as Record<string, Size>;

/**
 * Intrinsic `width`/`height` for a local image, derived from
 * `src/data/imageSizes.json` (regenerated by `scripts/generate-image-sizes.mjs`).
 * Spread onto an `<img>` so the browser reserves the right space before the
 * bitmap loads and the page never shifts.
 */
export function imageSize(src: string | undefined): { width?: number; height?: number } {
  if (!src) return {};
  const size = SIZES[src] ?? SIZES[src.split("?")[0]];
  return size ? { width: size.w, height: size.h } : {};
}
